  if(rest[0]==='from'){src=rest[1]==='any'?'':rest[1];const port=rest.indexOf('port');spec=port>=0?fwSpec(rest[port+1]+(proto?'/'+proto:''),src):[['any','any',src]]}else spec=fwSpec(rest.join(' '),'');
